// Verificar se está dentro do horário de funcionamento
const now = new Date();
const diaAtual = now.getDay(); // 0 = domingo
const horaAtual = now.toLocaleTimeString('pt-BR', { 
  hour: '2-digit', 
  minute: '2-digit',
  timeZone: 'America/Sao_Paulo' 
});

const horarios = $input.all()[3].json; // horarios_funcionamento
const horarioHoje = horarios.find(h => h.dia_semana === diaAtual);

let estaAberto = false;
let mensagemHorario = '';

if (horarioHoje && horarioHoje.ativo && horarioHoje.horario_abertura) {
  const abertura = horarioHoje.horario_abertura;
  const fechamento = horarioHoje.horario_fechamento;

  estaAberto = horaAtual >= abertura && horaAtual <= fechamento;
  mensagemHorario = `Horário: ${abertura} às ${fechamento}`;
} else {
  mensagemHorario = 'Hoje estamos fechados';
}

// Montar dados para IA
const dadosCliente = $input.all()[0].json[0] || {};
const cardapio = $input.all()[1].json;
const configuracoes = $input.all()[2].json;

// Converter configurações em objeto
const config = {};
configuracoes.forEach(c => {
  config[c.chave] = c.valor;
});

// Buscar últimas conversas para contexto
const mensagemAtual = $('Webhook WhatsApp').first().json.body;
const telefone = $('Webhook WhatsApp').first().json.from;
const nomeCliente = dadosCliente.nome || $('Webhook WhatsApp').first().json.pushName || 'Cliente';

return {
  json: {
    telefone: telefone,
    mensagem_usuario: mensagemAtual,
    cliente: {
      id: dadosCliente.id,
      nome: nomeCliente,
      endereco: dadosCliente.endereco,
      historico_pedidos: dadosCliente.historico_pedidos || []
    },
    cardapio: cardapio,
    configuracoes: config,
    horario: {
      esta_aberto: estaAberto,
      mensagem: mensagemHorario,
      dia_semana: diaAtual
    },
    timestamp: now.toISOString()
  }
};

// Carregar prompts de IA
const fs = require('fs');
const promptsPath = '/home/node/src/config/ai-prompts.json';
let aiPrompts = {};

try {
  const promptsContent = fs.readFileSync(promptsPath, 'utf8');
  aiPrompts = JSON.parse(promptsContent);
} catch (error) {
  console.error('Erro ao carregar prompts:', error);
  aiPrompts = { system_prompt: { role: 'Você é um atendente de pizzaria.' } };
}

const contexto = $input.first().json;
const historicoConversa = $input.last().json;

// Montar mensagens para OpenAI
const messages = [];

// System prompt
let systemPrompt = aiPrompts.system_prompt.role;
systemPrompt += '\n\n## Personalidade e Estilo:\n';
systemPrompt += aiPrompts.system_prompt.personality.join('\n');
systemPrompt += '\n\n## Suas Capacidades:\n';
systemPrompt += aiPrompts.system_prompt.capabilities.join('\n');
systemPrompt += '\n\n## Restrições Importantes:\n';
systemPrompt += aiPrompts.system_prompt.restrictions.join('\n');
systemPrompt += '\n\n## Regras Anti-Repetição:\n';
systemPrompt += aiPrompts.response_templates.avoid_repetition.rules.join('\n');

messages.push({
  role: 'system',
  content: systemPrompt
});

// Contexto atual
const contextoInfo = `
## CONTEXTO ATUAL:

**Pizzaria:** ${contexto.configuracoes.pizzaria_nome}
**Status:** ${contexto.horario.esta_aberto ? '🟢 ABERTO' : '🔴 FECHADO'}
**Horário:** ${contexto.horario.mensagem}
**Taxa Entrega:** R$ ${contexto.configuracoes.taxa_entrega}
**Tempo Médio:** ${contexto.configuracoes.tempo_medio_entrega} minutos

**Cliente:**
- Nome: ${contexto.cliente.nome}
- ID: ${contexto.cliente.id || 'Novo cliente'}
- Endereço cadastrado: ${contexto.cliente.endereco || 'Não cadastrado'}
- Total de pedidos anteriores: ${contexto.cliente.historico_pedidos?.length || 0}

**Cardápio Disponível:**
${JSON.stringify(contexto.cardapio, null, 2)}
`;

messages.push({
  role: 'system',
  content: contextoInfo
});

// Histórico de conversa (últimas 5 mensagens)
if (historicoConversa && historicoConversa.length > 0) {
  const ultimasMensagens = historicoConversa.slice(0, 5).reverse();

  ultimasMensagens.forEach(msg => {
    if (msg.tipo === 'recebida') {
      messages.push({
        role: 'user',
        content: msg.mensagem
      });
    } else if (msg.ia_resposta) {
      messages.push({
        role: 'assistant',
        content: msg.ia_resposta
      });
    }
  });
}

// Mensagem atual do usuário
messages.push({
  role: 'user',
  content: contexto.mensagem_usuario
});

// Instruções específicas baseadas no contexto
let instructionsContext = '';

if (!contexto.horario.esta_aberto) {
  instructionsContext = aiPrompts.context_instructions.greeting.after_hours;
} else if (contexto.cliente.historico_pedidos && contexto.cliente.historico_pedidos.length > 0) {
  instructionsContext = aiPrompts.context_instructions.greeting.returning_customer;
}

if (instructionsContext) {
  messages.push({
    role: 'system',
    content: `INSTRUÇÃO CONTEXTUAL: ${instructionsContext}`
  });
}

return {
  json: {
    messages: messages,
    contexto_original: contexto,
    max_tokens: 500,
    temperature: 0.7
  }
};

// Extrair resposta da IA
const iaResponse = $json.choices[0].message.content;
const contexto = $('Montar Prompt para IA').first().json.contexto_original;

// Analisar se a IA identificou alguma intenção específica
let intencao = 'conversa';
let dados_extraidos = {};

// Tentar extrair pedido da resposta (isso seria melhorado com function calling)
const respostaLower = iaResponse.toLowerCase();

if (respostaLower.includes('pedido') || respostaLower.includes('confirmar')) {
  intencao = 'fazer_pedido';
} else if (respostaLower.includes('cardápio') || respostaLower.includes('menu')) {
  intencao = 'consultar_cardapio';
} else if (respostaLower.includes('status') || respostaLower.includes('acompanhar')) {
  intencao = 'consultar_status';
}

return {
  json: {
    telefone: contexto.telefone,
    resposta_ia: iaResponse,
    intencao: intencao,
    dados_extraidos: dados_extraidos,
    cliente_id: contexto.cliente.id,
    mensagem_original: contexto.mensagem_usuario,
    timestamp: new Date().toISOString()
  }
};
